{
  "concepts": [
    {
      "conditions": [],
      "definition": "F6 is the source's family for claims, evidence, assessment and acceptance, covering EVALUATION §§1–5. Its instance premises are reliance on exact-subject claims for promotion, closure or release; finite evidence potentially observing a weaker or different subject or basis; fallible constructors; and a decision owner at each reliance boundary. These are conditions of governed work, not commitments or consequences of finite capacity alone.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 75,
          "quote": "They are conditions of the work\nthis family governs, not commitments, and do not follow from finite\ncapacity alone.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F1.%20Claims%2FFoundation%20to%20law%3A%20claims%2C%20evidence%2C%20assessment%20and%20acceptance",
          "start_line": 73
        }
      ],
      "key": "claims_evidence_assessment_acceptance",
      "label": "Claims, evidence, assessment and acceptance family"
    },
    {
      "conditions": [],
      "definition": "A load-bearing claim concerns an exact subject, claimed property and governing basis, with a witness-to-claim relation, nearest excluded weaker property and falsifier. Assurance may concern an authoritative composite subject rather than a single carrier.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 82,
          "quote": "a load-bearing claim names its exact subject, the property claimed, the governing basis, the relation between witness and claim, the nearest weaker property it excludes and its falsifier before a witness is selected",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F1.%20Claims%2FFoundation%20to%20law%3A%20claims%2C%20evidence%2C%20assessment%20and%20acceptance",
          "start_line": 82
        }
      ],
      "key": "exact_claim",
      "label": "Exact claim and assurance boundary"
    },
    {
      "conditions": [],
      "definition": "The semantic basis consists of constitutional and accepted-design relations defining a claim's meaning; the evidence basis consists of exact artifacts, events, logs, tests and observations used to evaluate it; the state projection is a current view derived from admitted semantic and evidence bases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 138,
          "quote": "Three bases stay distinct (P6, P1): the semantic basis, the constitutional\nand accepted-design relations that define what a claim means; the evidence\nbasis, the exact artifacts, events, logs, tests and observations used to\nevaluate it; and the state projection, a current view derived from admitted\nsemantic and evidence bases.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 134
        }
      ],
      "key": "semantic_evidence_projection_bases",
      "label": "Semantic basis, evidence basis and state projection"
    },
    {
      "conditions": [],
      "definition": "Structural conformance decides closed syntax, types, identities, references, bases and mechanically decidable predicates. Semantic fidelity decides meaning and materiality. A checker ordinarily decides the structural subset; semantic or authority decisions require an exact lawful model-supplied decision contract.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 166,
          "quote": "Structural conformance decides closed syntax, types, identities, references,\nbases and mechanically decidable predicates. Semantic fidelity decides\nmeaning and materiality. Structural success is evidence for semantic\nreview, not a substitute for it. A checker decides the structural subset; it claims a\nsemantic or authority subset only under an exact lawful decision contract\nsupplied by the model.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F2.%20Separation",
          "start_line": 161
        }
      ],
      "key": "structural_conformance_semantic_fidelity",
      "label": "Structural conformance and semantic fidelity"
    },
    {
      "conditions": [],
      "definition": "Independent assessment is assessment separate from construction, resting on authorship and evidence conditions. Constructor self-review remains construction output. EVALUATION defines what qualifies as independent; TICKETS owns required trigger boundaries and a governing basis may add boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 190,
          "quote": "This section decides what counts as independent assessment. Which\nboundaries require it is a policy choice of the Spec Method, owned by\n[TICKETS §7 Execution and verification authority separation](TICKETS.md#execution-and-verification-authority-separation-up-007);\na governing basis may add boundaries.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment",
          "start_line": 187
        }
      ],
      "key": "independent_assessment",
      "label": "Independent assessment"
    },
    {
      "conditions": [],
      "definition": "Author identity identifies the party responsible for the content of a realised subject. Actor identity identifies whoever performs an operation and is an identity, not an authority. Independence is assessed against authorship as well as evidence conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 224,
          "quote": "Author identity is the party responsible for the content of a realised\nsubject. It is distinct from actor identity, whoever performs one\noperation, which is an identity and not an authority",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F3.%20Independent%20assessment",
          "start_line": 217
        }
      ],
      "key": "author_actor_identity",
      "label": "Author identity and actor identity"
    },
    {
      "conditions": [],
      "definition": "A review return contains one core result per declared predicate actually evaluated, accompanying evidence and findings, uncertainty and invalidation conditions. A planned but unperformed predicate has no result; a recommendation is evidence rather than an applied disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 250,
          "quote": "A review returns one core result\n([FOUNDATIONS §4, Results](FOUNDATIONS.md#results)) for each declared\npredicate it evaluated, with: the exact subject and basis, the evidence\nconsulted, the findings ranked by consequence, each finding's evidence and\nthe smallest bounded correction, the residual uncertainty, and the\ninvalidation conditions.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results",
          "start_line": 244
        }
      ],
      "key": "review_return",
      "label": "Review result record"
    },
    {
      "conditions": [
        "A review returns findings with technical triage."
      ],
      "definition": "Technical triage is the assessor's evidence-bound assessment of each finding against the exact evaluated claim and basis. Severity grades consequence and is evaluation evidence. Priority, current-boundary effect and disposition belong to the decision owner. The adopting profile declares triage fields; the adopting Product binds scales.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 267,
          "quote": "Where a review returns findings with technical triage, the triage is the\nassessor's evidence-bound assessment of each finding against the exact\nevaluated claim and basis. Severity, the assessor's grade of consequence,\nis evaluation evidence. Priority, the effect on the current promotion\nboundary and the disposition are the decision owner's",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 263
        }
      ],
      "key": "technical_triage",
      "label": "Technical triage and decision values"
    },
    {
      "conditions": [],
      "definition": "The review projection covers the five core values satisfied, falsified, indeterminate, out_of_frame and invalid_basis. Its payload classes complete, indeterminate and not_applicable classify triage only; they are neither new results nor dispositions, priorities or lifecycle states. Absence of an evaluated predicate's result is distinct from every core value.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 283,
          "quote": "The projection of the finding-level triage payload is total over the core\nvalues of [FOUNDATIONS §4, Results](FOUNDATIONS.md#results). A predicate\nnot performed has no result and so no triage payload; the payload class\n`indeterminate` never stands for it. The payload classes `complete`,\n`indeterminate` and `not_applicable` classify the triage only; they are\nnot new results, dispositions, priorities or lifecycle states (P5, P1).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F4.%20Review%20results%2FResult%20and%20triage%20projection",
          "start_line": 278
        }
      ],
      "key": "core_result_triage_projection",
      "label": "Core result and triage payload domains"
    },
    {
      "conditions": [],
      "definition": "Acceptance is the decision owner's disposition over an unchanged evaluated subject, limited to the named instance and interval. Closure is satisfaction of a work item's stated closing condition. A human decision can be exercised directly or through an explicitly admitted bounded proxy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 321,
          "quote": "A work item closes by the condition it stated, not by a reviewer's approval;\na reviewer result is an input to closure, never the closure. Green labels,\ndocument counts, review counts and historical outcomes are not acceptance.\nA human decision may be exercised directly or through an explicitly admitted\nbounded proxy.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance",
          "start_line": 317
        }
      ],
      "key": "acceptance_and_closure",
      "label": "Acceptance, closure and bounded proxy"
    },
    {
      "conditions": [
        "The subject is a successor."
      ],
      "definition": "The successor disposition record identifies the exact immutable predecessor cut and one semantic disposition for every predecessor claim capable of affecting the successor. It is acceptance evidence; an intentional removal records a decision of the current Product authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 338,
          "quote": "Where the subject is a successor, its acceptance evidence includes the\nsuccessor disposition record of [RELEASE §9](RELEASE.md#9-successor-baseline-conservation-stdo-up-015)\n(STDO-UP-015), which states the law: the exact predecessor immutable cut\nthe successor evolves, and one semantic disposition for every predecessor\nclaim capable of affecting the successor.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance",
          "start_line": 330
        }
      ],
      "key": "successor_disposition_record",
      "label": "Successor disposition record"
    },
    {
      "conditions": [],
      "definition": "A finding is a defect reported against the exact evaluated claim. Blocking current promotion is the decision owner's act over a finding. EVALUATION §5 owns the blocking rule; profiles and work carriers add only domain triggers.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 346,
          "quote": "A finding is a defect a review reports against the exact claim it\nevaluated (§4). Blocking current promotion is the decision owner's act\nover that finding (§4, Result and triage projection). This section is the\none statement of when a finding can block; profiles and work carriers\nrefer to it and add only their domain triggers.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F5.%20Acceptance%2FWhen%20a%20finding%20blocks%20promotion",
          "start_line": 342
        }
      ],
      "key": "finding_promotion_block",
      "label": "Finding and promotion blocking"
    },
    {
      "conditions": [],
      "definition": "A realisation conforms to specification Σ when its interpreted behaviour satisfies Σ under a declared interpretation contract and independent judgment. Semantic conformance uses the governing semantic basis as Σ. Several realisations may conform without unique derivation or equality with an incumbent.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 393,
          "quote": "A realisation aⱼ conforms to a specification Σ when its interpreted behaviour\nsatisfies Σ under a declared interpretation contract (P1) and an independent\njudgment (P6). Several realisations may conform to one Σ; sufficiency does\nnot require unique derivation or equality with an incumbent.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 388
        }
      ],
      "key": "realisation_conformance",
      "label": "Realisation conformance"
    },
    {
      "conditions": [],
      "definition": "The equivalence ladder is an unordered list of four independent claim kinds: conformance; semantic equivalence of realisations, meaning identical interpreted behaviour on a stated domain including behaviour outside Σ; computational equivalence, meaning the same computed function at equal cost for declared workloads on declared architecture H; and categorical equivalence of categories and maps. Concept equivalence across bounded contexts is a different subject. Preservation of identities and composition by a map is a further separate claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 410,
          "quote": "Conformance, semantic equivalence, computational equivalence and\ncategorical equivalence are separate claims with separate evidence (P1,\nP6).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 397
        }
      ],
      "key": "equivalence_ladder",
      "label": "Unordered equivalence claim kinds"
    },
    {
      "conditions": [],
      "definition": "Layered sufficiency means a competent actor can derive a conformant next layer from each layer. Reconstructability requires a correct reconstruction route for the claim's span, rather than execution at every use. Failure to derive diagnoses the upper layer as unclear, contradictory, underspecified, insufficiently concrete or decomposable, or polluted by accidental lower-layer detail.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 436,
          "quote": "A specification arranged in layers is sufficient when\na competent actor can derive a conformant next layer from each layer; the\nderivation need not be unique, since different realisations may satisfy the\nsame upper layer, and the test is sufficiency, not determinism.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations",
          "start_line": 428
        }
      ],
      "key": "layered_sufficiency",
      "label": "Layered sufficiency and reconstructability"
    },
    {
      "conditions": [],
      "definition": "A reconstruction return reports a task building or assessing a successor member against its predecessor under three separate heads: semantic conservation of a disposed predecessor claim's meaning, judged by reading both texts against the disposition; demonstrated reduction of a corresponding deciding path's cost on a declared measure with both traces and tradeoffs; and mere relocation between owners or carriers without changed meaning or a traced deciding-path change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 480,
          "quote": "Demonstrated\nreduction: a deciding path of the successor costs less than the same path\nin the predecessor on a declared measure, shown by the trace of both paths\nwith the declared tradeoffs. Mere relocation: text moved from one owner or\ncarrier to another without a change in meaning and without a traced\nchange in any deciding path.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations%2FReturn%20of%20a%20reconstruction",
          "start_line": 473
        }
      ],
      "key": "reconstruction_return",
      "label": "Conservation, reduction and relocation return"
    },
    {
      "conditions": [],
      "definition": "F7 covers EVALUATION §§6–7 and CONFORMANCE and concerns fitness of realisations, frames and the method for their claims. Its instance premises are multiple possible realisations, fallible construction relied on by other actors, and finite qualification cases run within declared envelopes. These are work conditions, not commitments or consequences of finite capacity alone. Its named actor-change premise permits reacquisition of declared sources but not private memory.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 499,
          "quote": "They are conditions of\nthe work this family governs, not commitments, and do not follow from\nfinite capacity alone. P0's actor-change premise, that the actor of one\nstep need not be the actor of the next and may re-acquire declared sources\nbut not private memory, is cited by name.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F6.%20Conformance%20of%20realisations%2FFoundation%20to%20law%3A%20conformance%2C%20equivalence%20and%20qualification",
          "start_line": 495
        }
      ],
      "key": "conformance_equivalence_qualification",
      "label": "Conformance, equivalence and qualification family"
    },
    {
      "conditions": [],
      "definition": "EVALUATION §7 is the document grouping for qualification of frames and of the method; the heading itself adds no procedure beyond its subordinate sections.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 545,
          "quote": "## 7. Qualification of frames and of the method",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method",
          "start_line": 545
        }
      ],
      "key": "qualification_section",
      "label": "Qualification section"
    },
    {
      "conditions": [],
      "definition": "Candidate-frame qualification is proportional to its claims and binds the exact frame revision, actor envelope, evaluation family, basis class and evidence conditions evaluated. Its minimum evaluation comprises decision, reconstruction, sensitivity, irrelevance, basis, authority, counterexample, capability and result-consumption tests.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 578,
          "quote": "Qualification binds the exact frame revision, actor envelope, evaluation\nfamily, basis class and evidence conditions evaluated. It does not\ngeneralise to an unevaluated population by naming the frame generically\n(§1, the quantifier rule).",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FFrame%20qualification",
          "start_line": 575
        }
      ],
      "key": "frame_qualification",
      "label": "Frame qualification"
    },
    {
      "conditions": [],
      "definition": "Fit concerns whether an actor class can hold the frame within its envelope; context fit measures selected representation size against declared capacity. Adequate attention concerns actual operation of that frame and requires actual-use evidence for the declared class, tasks and conditions, assessed against source-derived expectations recorded before results are opened.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 591,
          "quote": "Whether the actor class\noperates the frame adequately is adequate attention, and only actual-use\nevidence establishes it: actors of the declared class apply the frame to\nits declared tasks under its declared conditions, and the results are\njudged against expectations recorded from the governing sources before the\nresults are opened, by an assessor under §3 where the claim needs\nindependent assessment.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FFrame%20qualification",
          "start_line": 585
        }
      ],
      "key": "fit_and_adequate_attention",
      "label": "Fit and adequate attention"
    },
    {
      "conditions": [],
      "definition": "Method self-qualification uses the ordinary qualification process, consuming the work boundary, construction and assessment relation and layered sufficiency. Its population is every claimed function and failure relation, with representative observations. Constructor, freeze, assessor, acceptance and release protocols are supplied by governing authority, not defined by this member.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 628,
          "quote": "The constructor, freeze, assessor, acceptance and\nrelease protocols are supplied by the governing authority; this member\ndefines none of them.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FMethod%20self-qualification",
          "start_line": 626
        }
      ],
      "key": "method_self_qualification",
      "label": "Method self-qualification"
    },
    {
      "conditions": [],
      "definition": "Named qualification operations are declare, activate, evaluate, conjoin, translate, audit_coverage and revise, alongside result consumption and material composition. They remain distinct populations; their meanings are owned by REFERENCE_FRAME §5, while this section specifies representative observations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 632,
          "quote": "The qualification population is every function and failure relation the\nmethod claims (REFERENCE_FRAME §5), each with its required representative\nobservations (P6):",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FMethod%20self-qualification",
          "start_line": 630
        }
      ],
      "key": "method_relation_population",
      "label": "Method functions and failure relations"
    },
    {
      "conditions": [],
      "definition": "Derived guidance includes compressions, frame packets, skills and other method projections. Recoverability is a benchmark in which a fresh actor uses only published documents to recover governing relations, with independently judged fidelity and measured reconstruction cost against the rc.2 corpus baseline.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 695,
          "quote": "For a selected activation, measure whether a fresh actor given\nonly the published documents recovers the governing relations with fidelity\njudged independently, and at what reconstruction cost, against the rc.2\ncorpus as baseline.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F7.%20Qualification%20of%20frames%20and%20of%20the%20method%2FMethod%20self-qualification",
          "start_line": 690
        }
      ],
      "key": "derived_guidance_recoverability",
      "label": "Derived guidance and recoverability benchmark"
    },
    {
      "conditions": [],
      "definition": "The source-disposition register records asserted conservation and ownership routes: UP-001 to §1; UP-022 across §§1,3,6,7; UP-008/RF-007 to §2 with frame binding elsewhere; AC-018/019 generic separation in §2 with a_c bindings elsewhere; UP-007 independence in §3 and blocking in §5 with trigger/traceability ownership in TICKETS; RF-013 and frame/method qualification to §7; UP-013 interval, AC-014 and proxy applications to §5; UP-015 acceptance evidence to §5 with full law and values in RELEASE §9; Reconstruction Litmus generic law to §6 and chain diagnosis to SPEC_METHOD §2; ticket judgment continuity to TICKETS §7 and reuse to ACTIVATION §7; reviewer triage to §4 with Executive-specific bindings retained in EXECUTIVE_BASELINE. It records, rather than proves, predecessor conservation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 719,
          "quote": "| Baseline reviewer result and triage projection | conserved; restated in §4 Result and triage projection with assessor and decision owner in place of the profile's Reviewer and Executive, over the core values of FOUNDATIONS §4 Results; the profile's triage fields and its steps are EXECUTIVE_BASELINE §5 and §12; row in the table below |",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EVALUATION.md#EVALUATION%2F8.%20Source%20dispositions",
          "start_line": 719
        }
      ],
      "key": "source_disposition_register",
      "label": "Source conservation and ownership register"
    },
    {
      "conditions": [],
      "definition": "EXECUTIVE_BASELINE is an optional tier-3 operational profile mapping Executive, Worker, Reviewer and specialist frames onto tier-1 and tier-2 law. It owns only its added bindings: direct-entry additions, empirical revision boundary, frame grants/limits/prohibitions and allocation, specialist catalogue, engagement procedure, Worker work-result readings, and adoption/configuration/qualification/closure records. Imported objects retain their external owners.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 15,
          "quote": "An operational\nprofile owns only its own bindings, the terms and choices it adds for its\noperation.",
          "section_id": "repo://stdo-v3-generation/claude/9aee01ffa76cfbde1a6b8f1153a25bd6d71c216e/source/standards/EXECUTIVE_BASELINE.md#EXECUTIVE_BASELINE",
          "start_line": 7
        }
      ],
      "key": "executive_baseline_profile",
      "label": "Optional Executive Baseline profile"
    },
    {
      "conditions": [],
      "definition": "The Worker frame carries constructor responsibility, the Reviewer frame assessor responsibility, and the Executive frame coordinator responsibility, disposing as decision owner or admitted proxy within an existing grant. Names bind allocated responsibilities and grant no authority themselves.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 48,
